export interface BallItem {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  mass: number;
}

export interface SimConfig {
  gravity: number;
  bounce: number;
  friction: number;
  spawnRadius: number;
  isPaused?: boolean;
}

export interface ControlsProps {
  config: SimConfig;
  onChangeConfig: (newConfig: Partial<SimConfig>) => void;
  ballCount: number;
  onClearBalls: () => void;
  onAddRandomBalls: (count: number) => void;
}

export interface PhysicsCanvasProps {
  config: SimConfig;
  balls?: BallItem[];
  onBallCountChange?: (count: number) => void;
  onAddBall?: (ball: BallItem) => void;
}

:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --bg-card: rgba(30, 41, 59, 0.7);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --accent-primary: #38bdf8;
  --accent-hover: #0ea5e9;
  --accent-secondary: #a855f7;
  --accent-danger: #ef4444;
  --accent-danger-hover: #dc2626;
  --border-color: #334155;
  --border-focus: #38bdf8;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -2px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -4px rgba(0, 0, 0, 0.4);
  --canvas-bg: #090d16;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 1rem 1.5rem 1.5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.app-header {
  text-align: center;
  margin-bottom: 1rem;
}

.app-title {
  font-size: 1.875rem;
  font-weight: 800;
  background: linear-gradient(135deg, #38bdf8, #818cf8, #c084fc);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.025em;
  margin-bottom: 0.25rem;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-secondary);
  font-weight: 400;
}

.instruction-banner {
  background: rgba(56, 189, 248, 0.1);
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  text-align: center;
  font-size: 0.875rem;
  color: #7dd3fc;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.sim-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 1.25rem;
  flex: 1;
  min-height: 600px;
}

@media (max-width: 960px) {
  .sim-layout {
    grid-template-columns: 1fr;
  }
}

.canvas-area {
  position: relative;
  background: var(--canvas-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.6), var(--shadow-md);
  min-height: 480px;
  display: flex;
  touch-action: none;
  cursor: crosshair;
}

.canvas-area.dragging {
  cursor: grabbing;
}

.physics-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.control-panel {
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  box-shadow: var(--shadow-md);
  height: fit-content;
}

.panel-section {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.section-title {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  padding-bottom: 0.4rem;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.control-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
}

.value-display {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.85rem;
  color: var(--accent-primary);
  background: rgba(15, 23, 42, 0.6);
  padding: 0.15rem 0.5rem;
  border-radius: 4px;
  border: 1px solid rgba(56, 189, 248, 0.2);
}

.control-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--bg-tertiary);
  border-radius: 3px;
  outline: none;
  transition: opacity 0.2s;
  cursor: pointer;
}

.control-slider:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 4px;
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-primary);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.6);
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.control-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: #7dd3fc;
}

.control-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: var(--accent-primary);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.6);
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.control-slider::-moz-range-thumb:hover {
  transform: scale(1.15);
  background: #7dd3fc;
}

.btn-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 0.6rem 1rem;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease, box-shadow 0.15s ease;
  user-select: none;
  -webkit-user-select: none;
}

.btn:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--accent-primary);
  color: #032b43;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  color: #ffffff;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.4);
}

.btn-secondary {
  background-color: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.btn-secondary:hover {
  background-color: #475569;
  border-color: rgba(255, 255, 255, 0.2);
}

.btn-danger {
  background-color: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.btn-danger:hover {
  background-color: var(--accent-danger);
  color: #ffffff;
  box-shadow: 0 0 12px rgba(239, 68, 68, 0.4);
}

.stats-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
}

.stats-card {
  background: rgba(15, 23, 42, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.stats-label {
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.stats-number {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent-primary);
}

@media (max-width: 640px) {
  .app-container {
    padding: 0.75rem;
  }

  .app-title {
    font-size: 1.5rem;
  }

  .canvas-area {
    min-height: 380px;
  }
}

import { ChangeEvent } from 'react';
import { ControlsProps } from '../types';

interface ExtendedControlsProps extends ControlsProps {
  isPaused?: boolean;
  onTogglePause?: () => void;
  onReset?: () => void;
}

export default function Controls({
  config,
  onChangeConfig,
  ballCount,
  onClearBalls,
  onAddRandomBalls,
  isPaused = false,
  onTogglePause,
  onReset,
}: ExtendedControlsProps) {
  const handleGravityChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({ gravity: parseFloat(e.target.value) });
  };

  const handleBounceChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({ bounce: parseFloat(e.target.value) });
  };

  const handleFrictionChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({ friction: parseFloat(e.target.value) });
  };

  const handleRadiusChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig?.({ spawnRadius: parseInt(e.target.value, 10) });
  };

  const handleReset = () => {
    if (onReset) {
      onReset();
    } else {
      onChangeConfig?.({
        gravity: 0.5,
        bounce: 0.75,
        friction: 0.99,
        spawnRadius: 20,
      });
    }
  };

  return (
    <div className="control-panel">
      <div className="panel-section">
        <h2 className="section-title">シミュレーション統計</h2>
        <div className="stats-container">
          <div className="stats-card">
            <span className="stats-label">現在のボール数</span>
            <span className="stats-number">{ballCount}</span>
          </div>
        </div>
      </div>

      <div className="panel-section">
        <h2 className="section-title">シミュレーション制御</h2>
        <div className="btn-group">
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => onTogglePause?.()}
            aria-label={isPaused ? 'シミュレーションを再開' : 'シミュレーションを一時停止'}
          >
            {isPaused ? '▶ 再開 (Resume)' : '⏸ 一時停止 (Pause)'}
          </button>
          <button
            type="button"
            className="btn btn-secondary"
            onClick={handleReset}
            aria-label="シミュレーション設定をリセット"
          >
            ↺ 初期設定にリセット
          </button>
        </div>
      </div>

      <div className="panel-section">
        <h2 className="section-title">物理パラメータ設定</h2>

        <div className="control-group">
          <label htmlFor="param-gravity" className="control-label">
            <span>重力加速度 (Gravity)</span>
            <span className="value-display">{config.gravity.toFixed(2)} G</span>
          </label>
          <input
            id="param-gravity"
            type="range"
            min="-1.0"
            max="2.0"
            step="0.05"
            value={config.gravity}
            onChange={handleGravityChange}
            aria-label="重力加速度"
            aria-valuetext={`${config.gravity.toFixed(2)} G`}
            className="control-slider"
          />
        </div>

        <div className="control-group">
          <label htmlFor="param-bounce" className="control-label">
            <span>反発係数 (Bounce)</span>
            <span className="value-display">{Math.round(config.bounce * 100)}%</span>
          </label>
          <input
            id="param-bounce"
            type="range"
            min="0.1"
            max="1.0"
            step="0.05"
            value={config.bounce}
            onChange={handleBounceChange}
            aria-label="反発係数"
            aria-valuetext={`${Math.round(config.bounce * 100)}%`}
            className="control-slider"
          />
        </div>

        <div className="control-group">
          <label htmlFor="param-friction" className="control-label">
            <span>空気抵抗・摩擦 (Friction)</span>
            <span className="value-display">{((1 - config.friction) * 100).toFixed(1)}% 減衰</span>
          </label>
          <input
            id="param-friction"
            type="range"
            min="0.95"
            max="1.0"
            step="0.005"
            value={config.friction}
            onChange={handleFrictionChange}
            aria-label="空気抵抗と摩擦"
            aria-valuetext={`${((1 - config.friction) * 100).toFixed(1)}% 減衰`}
            className="control-slider"
          />
        </div>

        <div className="control-group">
          <label htmlFor="param-spawn-radius" className="control-label">
            <span>生成ボール半径 (Size)</span>
            <span className="value-display">{config.spawnRadius}px</span>
          </label>
          <input
            id="param-spawn-radius"
            type="range"
            min="10"
            max="40"
            step="2"
            value={config.spawnRadius}
            onChange={handleRadiusChange}
            aria-label="生成ボール半径"
            aria-valuetext={`${config.spawnRadius}px`}
            className="control-slider"
          />
        </div>
      </div>

      <div className="panel-section">
        <h2 className="section-title">ボール操作</h2>
        <div className="btn-group">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={() => onAddRandomBalls?.(5)}
            aria-label="ボールを5個追加"
          >
            ボールを5個追加
          </button>
          <button
            type="button"
            className="btn btn-secondary"
            onClick={() => onAddRandomBalls?.(15)}
            aria-label="ボールを15個追加"
          >
            ボールを15個追加
          </button>
          <button
            type="button"
            className="btn btn-danger"
            onClick={() => onClearBalls?.()}
            aria-label="すべてのボールを消去"
          >
            全ボールを消去
          </button>
        </div>
      </div>
    </div>
  );
}

import { useRef, useEffect, useState, useCallback, PointerEvent as ReactPointerEvent } from 'react';
import { PhysicsCanvasProps, BallItem, SimConfig } from '../types';

const FALLBACK_CONFIG: SimConfig = {
  gravity: 0.5,
  bounce: 0.75,
  friction: 0.99,
  spawnRadius: 20,
  isPaused: false,
};

const BALL_COLORS = [
  '#38bdf8', // sky
  '#818cf8', // indigo
  '#c084fc', // purple
  '#f472b6', // pink
  '#fb7185', // rose
  '#34d399', // emerald
  '#fbbf24', // amber
  '#60a5fa', // blue
];

const getRandomColor = () => {
  return BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)];
};

export default function PhysicsCanvas({
  config = FALLBACK_CONFIG,
  balls: propBalls,
  onBallCountChange,
  onAddBall,
}: PhysicsCanvasProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // 物理演算用ボールリスト（高頻度更新のためrefで管理）
  const ballsRef = useRef<BallItem[]>(propBalls || []);

  // configが未定義や不完全なプロパティでも安全にフォールバック
  const safeConfig = {
    ...FALLBACK_CONFIG,
    ...(config || {}),
  };
  const configRef = useRef<SimConfig>(safeConfig);

  // configの変更を検知してconfigRef.currentを確実に更新
  useEffect(() => {
    configRef.current = {
      ...FALLBACK_CONFIG,
      ...(config || {}),
    };
  }, [config]);

  // 次のボールID管理用
  const nextIdRef = useRef<number>(1);

  // ドラッグ/スリングショット状態
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef<{ x: number; y: number } | null>(null);
  const dragCurrentRef = useRef<{ x: number; y: number } | null>(null);

  // 親から渡されたballsの同期
  useEffect(() => {
    if (propBalls !== undefined) {
      ballsRef.current = propBalls;
      if (propBalls.length > 0) {
        const maxId = Math.max(...propBalls.map((b) => b.id), 0);
        if (maxId >= nextIdRef.current) {
          nextIdRef.current = maxId + 1;
        }
      }
    }
  }, [propBalls]);

  // ボール追加用関数
  const createBall = useCallback(
    (x: number, y: number, vx: number, vy: number, radius: number): BallItem => {
      const validRadius = typeof radius === 'number' && !isNaN(radius) && radius > 0 ? radius : 20;
      const ball: BallItem = {
        id: nextIdRef.current++,
        x,
        y,
        vx,
        vy,
        radius: validRadius,
        color: getRandomColor(),
        mass: validRadius * validRadius, // 質量は断面積に比例
      };
      return ball;
    },
    []
  );

  // キャンバスのサイズ調整およびリサイズ時のボール境界補正
  const updateCanvasDimensions = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const rect = container.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const dpr = window.devicePixelRatio || 1;

    canvas.width = Math.floor(width * dpr);
    canvas.height = Math.floor(height * dpr);

    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.scale(dpr, dpr);
    }

    // リサイズ時にボールが画面外へ取り残されないよう境界内にクリップ
    if (width > 0 && height > 0 && ballsRef.current.length > 0) {
      for (let i = 0; i < ballsRef.current.length; i++) {
        const b = ballsRef.current[i];
        if (b.x + b.radius > width) {
          b.x = Math.max(b.radius, width - b.radius);
          if (b.vx > 0) b.vx = -b.vx * 0.5;
        } else if (b.x - b.radius < 0) {
          b.x = b.radius;
          if (b.vx < 0) b.vx = -b.vx * 0.5;
        }

        if (b.y + b.radius > height) {
          b.y = Math.max(b.radius, height - b.radius);
          if (b.vy > 0) b.vy = -b.vy * 0.5;
        } else if (b.y - b.radius < 0) {
          b.y = b.radius;
          if (b.vy < 0) b.vy = -b.vy * 0.5;
        }
      }
    }
  }, []);

  useEffect(() => {
    updateCanvasDimensions();
    const resizeObserver = new ResizeObserver(() => {
      updateCanvasDimensions();
    });

    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    window.addEventListener('resize', updateCanvasDimensions);
    return () => {
      resizeObserver.disconnect();
      window.removeEventListener('resize', updateCanvasDimensions);
    };
  }, [updateCanvasDimensions]);

  // 物理演算ループ & レンダリングループ
  useEffect(() => {
    let animationFrameId: number;

    const step = () => {
      const canvas = canvasRef.current;
      const container = containerRef.current;
      if (!canvas || !container) {
        animationFrameId = requestAnimationFrame(step);
        return;
      }

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        animationFrameId = requestAnimationFrame(step);
        return;
      }

      const rect = container.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      // 未定義プロパティ安全ガード（gravity, bounce, friction, spawnRadius）
      const currentConfig = {
        ...FALLBACK_CONFIG,
        ...(configRef.current || {}),
      };

      const isPaused = Boolean(currentConfig.isPaused);
      const balls = ballsRef.current;

      const gravity = typeof currentConfig.gravity === 'number' ? currentConfig.gravity : 0.5;
      const bounce = typeof currentConfig.bounce === 'number' ? currentConfig.bounce : 0.75;
      const friction = typeof currentConfig.friction === 'number' ? currentConfig.friction : 0.99;
      const spawnRadius = typeof currentConfig.spawnRadius === 'number' ? currentConfig.spawnRadius : 20;

      // 1. 物理シミュレーションの更新（一時停止でない場合）
      if (!isPaused && width > 0 && height > 0) {
        // 位置の更新と重力・摩擦・壁バウンド
        for (let i = 0; i < balls.length; i++) {
          const b = balls[i];

          b.vy += gravity;
          b.vx *= friction;
          b.vy *= friction;

          b.x += b.vx;
          b.y += b.vy;

          // 左壁との衝突判定
          if (b.x - b.radius < 0) {
            b.x = b.radius;
            b.vx = -b.vx * bounce;
          }
          // 右壁との衝突判定
          else if (b.x + b.radius > width) {
            b.x = width - b.radius;
            b.vx = -b.vx * bounce;
          }

          // 天井との衝突判定
          if (b.y - b.radius < 0) {
            b.y = b.radius;
            b.vy = -b.vy * bounce;
          }
          // 床との衝突判定
          else if (b.y + b.radius > height) {
            b.y = height - b.radius;
            b.vy = -b.vy * bounce;

            // 微小な上下動による床でのジッター防止
            if (Math.abs(b.vy) < 0.2 && Math.abs(gravity) > 0) {
              b.vy = 0;
            }
          }
        }

        // ボール同士の衝突判定・応答
        const ballsLen = balls.length;
        for (let i = 0; i < ballsLen; i++) {
          for (let j = i + 1; j < ballsLen; j++) {
            const b1 = balls[i];
            const b2 = balls[j];

            const dx = b2.x - b1.x;
            const dy = b2.y - b1.y;
            const distSq = dx * dx + dy * dy;
            const minDist = b1.radius + b2.radius;

            if (distSq < minDist * minDist && distSq > 0) {
              const dist = Math.sqrt(distSq);
              const nx = dx / dist;
              const ny = dy / dist;

              // 相対速度
              const rvx = b2.vx - b1.vx;
              const rvy = b2.vy - b1.vy;
              const velAlongNormal = rvx * nx + rvy * ny;

              // 近づいている場合のみ衝突応答を計算（離脱中は処理しない）
              if (velAlongNormal < 0) {
                const restitution = bounce;
                const m1 = b1.mass || 1;
                const m2 = b2.mass || 1;
                const impulse =
                  (-(1 + restitution) * velAlongNormal) /
                  (1 / m1 + 1 / m2);

                const impulseX = impulse * nx;
                const impulseY = impulse * ny;

                b1.vx -= (1 / m1) * impulseX;
                b1.vy -= (1 / m1) * impulseY;
                b2.vx += (1 / m2) * impulseX;
                b2.vy += (1 / m2) * impulseY;

                // 重なり補正（位置補正）
                const percent = 0.8;
                const slop = 0.01;
                const penetration = minDist - dist;
                if (penetration > slop) {
                  const correction =
                    (Math.max(penetration - slop, 0) /
                      (1 / m1 + 1 / m2)) *
                    percent;
                  const corrX = correction * nx;
                  const corrY = correction * ny;

                  b1.x -= (1 / m1) * corrX;
                  b1.y -= (1 / m1) * corrY;
                  b2.x += (1 / m2) * corrX;
                  b2.y += (1 / m2) * corrY;
                }
              }
            }
          }
        }
      }

      // 2. 描画
      ctx.clearRect(0, 0, width, height);

      // 背景グリッド描画（視覚的なガイドライン）
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
      ctx.lineWidth = 1;
      const gridSize = 40;
      for (let x = 0; x < width; x += gridSize) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = 0; y < height; y += gridSize) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // ボールの描画
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];

        // ボール本体のグラデーション
        const grad = ctx.createRadialGradient(
          b.x - b.radius * 0.3,
          b.y - b.radius * 0.3,
          b.radius * 0.1,
          b.x,
          b.y,
          b.radius
        );
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, b.color);
        grad.addColorStop(1, '#000000');

        ctx.beginPath();
        ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
        ctx.fillStyle = grad;
        ctx.shadowColor = b.color;
        ctx.shadowBlur = 8;
        ctx.fill();
        ctx.shadowBlur = 0;

        // ハイライトの輪郭
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.stroke();
      }

      // 3. スリングショット（発射準備）ガイドの描画
      if (dragStartRef.current && dragCurrentRef.current) {
        const start = dragStartRef.current;
        const current = dragCurrentRef.current;

        // 引っ張りライン
        ctx.beginPath();
        ctx.moveTo(start.x, start.y);
        ctx.lineTo(current.x, current.y);
        ctx.strokeStyle = 'rgba(56, 189, 248, 0.8)';
        ctx.lineWidth = 2;
        ctx.setLineDash([4, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        // 発射予測ベクトルライン（逆方向）
        const vx = (start.x - current.x) * 0.15;
        const vy = (start.y - current.y) * 0.15;
        const launchTargetX = start.x + vx * 6;
        const launchTargetY = start.y + vy * 6;

        ctx.beginPath();
        ctx.moveTo(start.x, start.y);
        ctx.lineTo(launchTargetX, launchTargetY);
        ctx.strokeStyle = 'rgba(244, 114, 182, 0.8)';
        ctx.lineWidth = 3;
        ctx.stroke();

        // 発射予定ボールのゴーストプレビュー
        ctx.beginPath();
        ctx.arc(start.x, start.y, spawnRadius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';
        ctx.strokeStyle = '#38bdf8';
        ctx.lineWidth = 2;
        ctx.fill();
        ctx.stroke();
      }

      animationFrameId = requestAnimationFrame(step);
    };

    animationFrameId = requestAnimationFrame(step);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // ポインターイベントによるボール生成・投擲
  const getCanvasCoords = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    };
  };

  const handlePointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    const coords = getCanvasCoords(e);
    dragStartRef.current = coords;
    dragCurrentRef.current = coords;
    setIsDragging(true);
  };

  const handlePointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!isDragging) return;
    dragCurrentRef.current = getCanvasCoords(e);
  };

  const handlePointerUp = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!isDragging || !dragStartRef.current || !dragCurrentRef.current) {
      setIsDragging(false);
      dragStartRef.current = null;
      dragCurrentRef.current = null;
      return;
    }

    try {
      e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {
      // 既にキャプチャが外れている場合は無視
    }

    const start = dragStartRef.current;
    const current = dragCurrentRef.current;
    const dx = start.x - current.x;
    const dy = start.y - current.y;

    // クリック（移動距離が極小）かスリングショット（引っ張り）かを判定
    let vx = 0;
    let vy = 0;
    const dragDistance = Math.hypot(dx, dy);

    if (dragDistance > 6) {
      // スリングショット: 引っ張った反対方向に初速を付与
      const powerMultiplier = 0.18;
      vx = dx * powerMultiplier;
      vy = dy * powerMultiplier;
    } else {
      // クリックのみの場合はわずかなランダム横速度
      vx = (Math.random() - 0.5) * 4;
      vy = Math.random() * 2;
    }

    const currentSpawnRadius =
      typeof configRef.current?.spawnRadius === 'number'
        ? configRef.current.spawnRadius
        : FALLBACK_CONFIG.spawnRadius;

    const newBall = createBall(start.x, start.y, vx, vy, currentSpawnRadius);

    if (onAddBall) {
      onAddBall(newBall);
    } else {
      ballsRef.current = [...ballsRef.current, newBall];
      onBallCountChange?.(ballsRef.current.length);
    }

    setIsDragging(false);
    dragStartRef.current = null;
    dragCurrentRef.current = null;
  };

  const handlePointerCancel = () => {
    setIsDragging(false);
    dragStartRef.current = null;
    dragCurrentRef.current = null;
  };

  return (
    <div
      ref={containerRef}
      className={`canvas-area ${isDragging ? 'dragging' : ''}`}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerCancel}
      role="application"
      aria-label="物理シミュレーションキャンバス。クリックまたはドラッグしてボールを発射できます。"
      tabIndex={0}
    >
      <canvas ref={canvasRef} className="physics-canvas" />
    </div>
  );
}

import { useState, useCallback } from 'react';
import { BallItem, SimConfig } from './types';
import Controls from './components/Controls';
import PhysicsCanvas from './components/PhysicsCanvas';

const DEFAULT_CONFIG: SimConfig = {
  gravity: 0.5,
  bounce: 0.75,
  friction: 0.99,
  spawnRadius: 20,
  isPaused: false,
};

const BALL_COLORS = [
  '#38bdf8', // sky
  '#818cf8', // indigo
  '#c084fc', // purple
  '#f472b6', // pink
  '#fb7185', // rose
  '#34d399', // emerald
  '#fbbf24', // amber
  '#60a5fa', // blue
];

const getRandomColor = () => {
  return BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)];
};

// 初期表示用のボールデータ生成（開いた直後からシミュレーションが動作）
const createInitialBalls = (): BallItem[] => {
  const initialData = [
    { x: 120, y: 100, vx: 3.5, vy: -1.0, radius: 24, color: '#38bdf8' },
    { x: 220, y: 80, vx: -2.0, vy: 1.5, radius: 18, color: '#c084fc' },
    { x: 320, y: 150, vx: 2.8, vy: -2.5, radius: 28, color: '#34d399' },
    { x: 420, y: 120, vx: -3.2, vy: 0.5, radius: 16, color: '#fbbf24' },
    { x: 500, y: 70, vx: 1.5, vy: 2.0, radius: 22, color: '#f472b6' },
  ];

  return initialData.map((b, index) => ({
    id: index + 1,
    x: b.x,
    y: b.y,
    vx: b.vx,
    vy: b.vy,
    radius: b.radius,
    color: b.color,
    mass: b.radius * b.radius,
  }));
};

export default function App() {
  const [config, setConfig] = useState<SimConfig>(DEFAULT_CONFIG);
  const [balls, setBalls] = useState<BallItem[]>(createInitialBalls);

  // パラメータ変更ハンドラ
  const handleChangeConfig = useCallback((newConfig: Partial<SimConfig>) => {
    setConfig((prev) => ({
      ...DEFAULT_CONFIG,
      ...prev,
      ...newConfig,
    }));
  }, []);

  // 一時停止・再開トグル
  const handleTogglePause = useCallback(() => {
    setConfig((prev) => ({
      ...DEFAULT_CONFIG,
      ...prev,
      isPaused: !prev.isPaused,
    }));
  }, []);

  // 設定リセット
  const handleResetConfig = useCallback(() => {
    setConfig(DEFAULT_CONFIG);
  }, []);

  // 全ボール消去
  const handleClearBalls = useCallback(() => {
    setBalls([]);
  }, []);

  // ランダムボール追加
  const handleAddRandomBalls = useCallback((count: number) => {
    setBalls((prev) => {
      const highestId = prev.reduce((max, b) => Math.max(max, b.id), 0);
      const newBalls: BallItem[] = [];

      for (let i = 0; i < count; i++) {
        const radius = Math.floor(Math.random() * 16) + 14; // 14px〜30px
        const ball: BallItem = {
          id: highestId + i + 1,
          x: Math.random() * 300 + 80,
          y: Math.random() * 150 + 50,
          vx: (Math.random() - 0.5) * 8,
          vy: (Math.random() - 0.5) * 4,
          radius,
          color: getRandomColor(),
          mass: radius * radius,
        };
        newBalls.push(ball);
      }

      return [...prev, ...newBalls];
    });
  }, []);

  // キャンバスクリック/スリングショットでボール追加（App側で一元管理）
  const handleAddBall = useCallback((ball: BallItem) => {
    setBalls((prev) => [...prev, ball]);
  }, []);

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">物理演算 2Dボールシミュレーター</h1>
        <p className="app-subtitle">
          重力・弾性反発・ボール同士の運動量保存衝突をリアルタイム計算
        </p>
      </header>

      <div className="instruction-banner">
        <span>💡 操作方法:</span>
        <span>キャンバス内をクリック、またはドラッグして引っ張って離すと狙った方向へボールを発射できます。</span>
      </div>

      <main className="sim-layout">
        <PhysicsCanvas
          config={config}
          balls={balls}
          onAddBall={handleAddBall}
        />

        <Controls
          config={config}
          onChangeConfig={handleChangeConfig}
          ballCount={balls.length}
          onClearBalls={handleClearBalls}
          onAddRandomBalls={handleAddRandomBalls}
          isPaused={Boolean(config.isPaused)}
          onTogglePause={handleTogglePause}
          onReset={handleResetConfig}
        />
      </main>
    </div>
  );
}
